"""Strict source decoding, using generated bytes only and no private memory."""
import codecs
import asyncio
import importlib
from types import SimpleNamespace

import pytest


def decoder():
    return importlib.import_module('backend.retrieval.decoding')


def policy(encoding='auto', overrides=None):
    return SimpleNamespace(encoding=encoding, overrides=overrides or {})


def test_existing_corpus_indexes_gbk_bytes_without_changing_source(tmp_path, monkeypatch):
    from backend.retrieval.config import LocalMemoryConfig
    from backend.retrieval.local_memory import LocalMemoryService
    monkeypatch.delenv('LOCAL_MEMORY_STARTUP_GATE', raising=False)
    monkeypatch.delenv('LOCAL_MEMORY_STARTUP_NONCE', raising=False)
    monkeypatch.setenv('WEB_CONCURRENCY', '1')
    monkeypatch.setenv('UVICORN_WORKERS', '1')
    class Encoder:
        fingerprint = 'synthetic-gbk-decoding-v1'
        class tokenizer:
            @staticmethod
            def encode(text, add_special_tokens=True):
                return list(range(len(text)))
        def encode_documents(self, texts):
            return [[1.0] + [0.0] * 383 for text in texts]
        def encode_query(self, text):
            return [1.0] + [0.0] * 383
    async def scenario():
        source = tmp_path / 'synthetic-notes'
        source.mkdir()
        text = '这是一段中文记忆：用户喜欢简洁准确的回答，请记住常用偏好。'
        data = text.encode('gbk')
        path = source / 'synthetic.txt'
        path.write_bytes(data)
        service = LocalMemoryService(LocalMemoryConfig(source_dir='synthetic-notes', state_dir='synthetic-index'),
            project_root=tmp_path, encoder=Encoder())
        await service.start()
        try:
            await asyncio.wait_for(asyncio.shield(service._startup_task), timeout=10)
            assert service.status_snapshot()['status'] == 'ready', service.status_snapshot()
            result = await service.prepare_user_turn('请回忆回答偏好', enabled=True, context_validator=lambda _: True)
            assert result.memory_texts == (text,)
            assert path.read_bytes() == data
        finally:
            await service.shutdown()
    asyncio.run(scenario())


@pytest.mark.parametrize(('encoding', 'text'), [
    ('ascii', 'Preferences: concise answers.\r\nNext page\fKeep tabs\tintact.'),
    ('UTF-8', '记忆 café 😀\r\n保留原文。'),
    ('utf-8-sig', '记忆 café 😀\r\n保留原文。'),
    ('GBK', '这是一段中文记忆：用户喜欢简洁准确的回答，请记住常用偏好。'),
    ('GB18030', '这是一段中文记忆：扩展汉字𠀀与表情😀。'),
    ('Big5', '這是一段繁體中文記憶：使用者喜歡簡潔準確的回答。'),
    ('ISO-8859-1', 'Préférences : café, résumé, Grüße für Straße.'),
    ('Shift_JIS', 'これは日本語の記憶です。簡潔で正確な回答を好みます。'),
    ('EUC-KR', '이것은 한국어 기억입니다. 간결하고 정확한 답변을 선호합니다.'),
    ('UTF-16', '记忆 😀\r\n保留原文。'),
    ('UTF-16LE', '你好'),
    ('UTF-16BE', '你好'),
])
def test_explicit_supported_encodings_decode_exact_text(encoding, text):
    result = decoder().decode_source(text.encode(encoding), 'synthetic.txt', policy(encoding))
    assert result == text


@pytest.mark.parametrize(('encoding', 'text'), [
    ('ascii', 'Remember: the user prefers concise answers.'),
    ('utf-8', '这是 UTF-8 记忆。'),
    ('utf-8-sig', '这是 UTF-8 记忆。'),
    ('gbk', '这是一段中文记忆：用户喜欢简洁准确的回答，请记住常用偏好。'),
    ('gb18030', '这是一段中文记忆：用户喜欢简洁准确的回答，扩展汉字𠀀与表情😀。'),
    ('big5', '這是一段繁體中文記憶：使用者喜歡簡潔準確的回答，請記住常用偏好。'),
    ('shift_jis', 'これは日本語の記憶です。ユーザーは簡潔で正確な回答を好みます。'),
    ('euc_kr', '이것은 한국어 기억입니다. 사용자는 간결하고 정확한 답변을 선호합니다.'),
    ('iso8859_1', 'Préférences mémorisées : réponses courtes et précises, café et résumé.'),
    ('utf-16', '这是中文记忆。用户喜欢简洁回答。'),
    ('utf-16-le', '这是中文记忆。用户喜欢简洁回答。'),
    ('utf-16-be', '这是中文记忆。用户喜欢简洁回答。'),
])
def test_auto_decodes_representative_multilingual_samples(encoding, text):
    assert decoder().decode_source(text.encode(encoding), 'synthetic.md', policy()) == text


@pytest.mark.parametrize(('bom', 'codec'), [(codecs.BOM_UTF16_LE, 'utf-16-le'),
    (codecs.BOM_UTF16_BE, 'utf-16-be'), (codecs.BOM_UTF8, 'utf-8')])
def test_compatible_bom_is_removed_for_explicit_and_auto(bom, codec):
    text = '原文\r\n下一行。'
    data = bom + text.encode(codec)
    assert decoder().decode_source(data, 'synthetic.txt', policy(codec)) == text
    assert decoder().decode_source(data, 'synthetic.txt', policy()) == text


def test_exact_relative_override_takes_precedence_and_resolves_short_utf16_ambiguity():
    config = policy('ascii', {'sub/ambiguous.txt': 'UTF-16LE'})
    assert decoder().decode_source('你好'.encode('utf-16-le'), 'sub/ambiguous.txt', config) == '你好'
    assert decoder().decode_source(b'plain ASCII', 'other.txt', config) == 'plain ASCII'


def test_generic_utf16_requires_bom_instead_of_assuming_native_byte_order():
    with pytest.raises(ValueError):
        decoder().decode_source('你好'.encode('utf-16-le'), 'synthetic.txt', policy('utf-16'))


@pytest.mark.parametrize('data', [b'\xff\xfe\xff', b'\xfe\xff\x00', b'\xef\xbb\xbf\xff'])
def test_malformed_recognized_bom_never_falls_back_to_another_codec(data):
    with pytest.raises(ValueError):
        decoder().decode_source(data, 'synthetic.txt', policy())


@pytest.mark.parametrize('data', [codecs.BOM_UTF32_LE + b'A\x00\x00\x00',
    codecs.BOM_UTF32_BE + b'\x00\x00\x00A'])
def test_unsupported_utf32_bom_is_rejected_before_utf16_detection(data):
    with pytest.raises(ValueError):
        decoder().decode_source(data, 'synthetic.txt', policy())


@pytest.mark.parametrize(('data', 'encoding'), [
    (codecs.BOM_UTF8 + b'text', 'iso-8859-1'),
    (codecs.BOM_UTF16_BE + '原文'.encode('utf-16-be'), 'utf-16-le'),
    (b'\xff', 'utf-8'), (b'\x81', 'gbk'),
    (b'\x81', 'iso-8859-1'), (b'\x00text', 'ascii'),
    ('bad\x01control'.encode(), 'utf-8'),
    ('bad\ufffe'.encode(), 'utf-8'),
])
def test_explicit_decoding_rejects_invalid_bytes_conflicting_bom_and_binary_controls(data, encoding):
    with pytest.raises(ValueError):
        decoder().decode_source(data, 'synthetic.txt', policy(encoding))


@pytest.mark.parametrize('data', [bytes(range(256)) * 4, b'\x89PNG\r\n\x1a\n' + bytes(range(256)),
    b'\x00' * 100])
def test_auto_binary_data_is_not_blindly_decoded_as_latin1(data):
    with pytest.raises(ValueError):
        decoder().decode_source(data, 'synthetic.txt', policy())


def test_existing_utf8_replacement_character_is_preserved_without_replacement_decoding():
    text = '原文中确实包含 \ufffd，保留它。\r\n'
    assert decoder().decode_source(text.encode(), 'synthetic.txt', policy()) == text


@pytest.mark.parametrize('encoding', ['utf-32', 'cp1252', 'koi8-r', '', True, None])
def test_normalizer_rejects_unapproved_or_invalid_codec_names(encoding):
    with pytest.raises(ValueError):
        decoder().normalize_encoding(encoding)


def test_encoding_fingerprint_normalizes_aliases_and_override_order():
    first = policy('UTF8', {'b.txt': 'latin1', 'a.md': 'UTF16LE'})
    equivalent = policy('utf-8', {'a.md': 'utf-16-le', 'b.txt': 'iso-8859-1'})
    changed = policy('utf-8', {'a.md': 'utf-16-be', 'b.txt': 'iso-8859-1'})
    assert decoder().decoding_fingerprint(first) == decoder().decoding_fingerprint(equivalent)
    assert decoder().decoding_fingerprint(first) != decoder().decoding_fingerprint(changed)
